const SB = 'https://gojpffsrxybbpbdzzrvs.supabase.co';
const SBH = { apikey: '{{SUPABASE_SERVICE_ROLE_KEY}}', Authorization: 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}', 'Content-Type': 'application/json' };
const qy = $input.first().json.query || {};
const email = String(qy.e || '').trim().toLowerCase();
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return [{ json: { ok: false, message: 'Invalid link.' } }];
function q(params){ const p=[]; for (const k of Object.keys(params)) p.push(encodeURIComponent(k)+'='+encodeURIComponent(params[k])); return p.join('&'); }
await this.helpers.httpRequest({ method: 'PATCH', url: SB + '/rest/v1/leads?' + q({ email: 'eq.' + email, primary_venture: 'eq.mm_ctrl' }), headers: SBH, body: { churned_at: new Date().toISOString() }, json: true });
const leadArr = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/leads?' + q({ select: 'id', email: 'eq.' + email, primary_venture: 'eq.mm_ctrl' }), headers: SBH, json: true }) || [];
for (const l of leadArr) {
  await this.helpers.httpRequest({ method: 'PATCH', url: SB + '/rest/v1/acquisition_sends?' + q({ lead_id: 'eq.' + l.id, status: 'in.(queued,approved)' }), headers: SBH, body: { status: 'suppressed' }, json: true });
}
await this.helpers.httpRequest({ method: 'POST', url: SB + '/rest/v1/audit_log', headers: SBH, body: [{ actor: 'system', event_type: 'acquisition-unsubscribe', display_message: 'CTRL nurture unsubscribe: ' + email, details: JSON.stringify({ email, lane: 'mm_ctrl' }) }], json: true });
return [{ json: { ok: true, message: 'You are unsubscribed. No more emails from CTRL.' } }];
